hl.bind("SUPER + SHIFT + CTRL + left", function()
    local window = hl.get_active_window()
    if not window then
        return
    end
    if window.floating then
        hl.dispatch(hl.dsp.window.move({ x = -30, y = 0, relative = true }))
    else
        hl.dispatch(hl.dsp.window.swap({ direction = "left" }))
    end
end, { description = "Move or swap window left" })
hl.bind("SUPER + SHIFT + CTRL + right", function()
    local window = hl.get_active_window()
    if not window then
        return
    end
    if window.floating then
        hl.dispatch(hl.dsp.window.move({ x = 30, y = 0, relative = true }))
    else
        hl.dispatch(hl.dsp.window.swap({ direction = "right" }))
    end
end, { description = "Move or swap window right" })
hl.bind("SUPER + SHIFT + CTRL + up", function()
    local window = hl.get_active_window()
    if not window then
        return
    end
    if window.floating then
        hl.dispatch(hl.dsp.window.move({ x = 0, y = -30, relative = true }))
    else
        hl.dispatch(hl.dsp.window.swap({ direction = "up" }))
    end
end, { description = "Move or swap window up" })
hl.bind("SUPER + SHIFT + CTRL + down", function()
    local window = hl.get_active_window()
    if not window then
        return
    end
    if window.floating then
        hl.dispatch(hl.dsp.window.move({ x = 0, y = 30, relative = true }))
    else
        hl.dispatch(hl.dsp.window.swap({ direction = "down" }))
    end
end, { description = "Move or swap window down" })

